import 'package:flutter_sizer/flutter_sizer.dart';

FlutterSizer(
  builder: (context, orientation, screenType) {
    return Scaffold(
      body: Center(
        child: Container(
          width: 50.w, // 50% of screen width
          height: 20.h, // 20% of screen height
          color: Colors.blue,
        ),
      ),
    );
  },
);
